const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lacRouge = ee.Geometry.Point([-70.9167, 45.7083]); // Lac Rouge, Quebec
  const roi = lacRouge.buffer(500); // 500m buffer around lake
  const date1Start = '2024-06-14';
  const date1End = '2024-06-28';
  const date2Start = '2025-06-08';
  const date2End = '2025-06-22';

  // Helper: Get water area from Sentinel-2 collection
  function getWaterArea(collection, periodName) {
    // Cloud masking for Sentinel-2
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    const filtered = collection
      .filterBounds(roi)
      .filterDate(date1Start, date1End)
      .map(maskS2clouds);

    const size = filtered.size();
    print(periodName + ' Sentinel-2 Images:', size);

    if (size.getInfo() === 0) {
      return { area: null, count: 0, reason: 'No images' };
    }

    // Create median composite and calculate NDWI
    const composite = filtered.median();
    const ndwi = composite.normalizedDifference(['B3', 'B8']); // Green - NIR / Green + NIR
    const water = ndwi.gt(0.0); // NDWI > 0 indicates water

    // Count water pixels
    const stats = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: 10, // Sentinel-2 resolution
      maxPixels: 1e9
    });
    const count = stats.get('nd').getInfo();
    print(periodName + ' Water Pixels:', count);
    return { area: count * 10 * 10, count: count, reason: null }; // area in m²
  }

  // 2. Data Acquisition for both periods
  const s2Col1 = ee.ImageCollection('COPERNICUS/S2_SR');
  const s2Col2 = ee.ImageCollection('COPERNICUS/S2_SR');

  const area1 = getWaterArea(s2Col1, '2024');
  const area2 = getWaterArea(s2Col2, '2025');

  // Fallback to Landsat if Sentinel-2 has no images
  let fallbackUsed = false;
  if (area1.reason === 'No images' || area2.reason === 'No images') {
    print('Trying Landsat 8/9 fallback...');
    fallbackUsed = true;
    // Landsat 8/9 collection
    const landsatCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'));

    function getLandsatWaterArea(startDate, endDate, periodName) {
      const filtered = landsatCol
        .filterBounds(roi)
        .filterDate(startDate, endDate);
      const size = filtered.size();
      print(periodName + ' Landsat Images:', size);
      if (size.getInfo() === 0) {
        return { area: null, count: 0 };
      }
      // Use SWIR1 (B6) and Green (B3) for water detection: B3/B6 > 1.5
      const composite = filtered.median();
      const waterIndex = composite.select('SR_B3').divide(composite.select('SR_B6')).gt(1.5);
      const stats = waterIndex.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 30,
        maxPixels: 1e9
      });
      const count = stats.get('SR_B3').getInfo();
      print(periodName + ' Landsat Water Pixels:', count);
      return { area: count * 30 * 30, count: count };
    }

    if (area1.reason === 'No images') {
      area1 = getLandsatWaterArea(date1Start, date1End, '2024');
    }
    if (area2.reason === 'No images') {
      area2 = getLandsatWaterArea(date2Start, date2End, '2025');
    }
  }

  // 3. Check for no data (C1)
  if (area1.count === 0 || area2.count === 0) {
    print('No valid images found for one or both periods.');
    print('<answer>C1</answer>');
    return;
  }

  // 4. Check for no valid pixels (C2)
  if (area1.count === null || area2.count === null) {
    print('No valid pixels after processing.');
    print('<answer>C2</answer>');
    return;
  }

  // 5. Calculate change
  const change = ((area1.count - area2.count) / area1.count) * 100;
  print('Water Pixel Counts - 2024:', area1.count, '2025:', area2.count);
  print('Percentage Decrease:', change.toFixed(2) + '%');

  // 6. Validation & Final Answer
  if (isNaN(change) || !isFinite(change)) {
    print('<answer>C3</answer>');
  } else if (change > 90) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
